175	/// names, and push. `agent` is the agent side's plan, `None` for the
176	/// work side.
177	fn publish_title(
178	    plan: &InitPlan,
179	    side: &str,
180	    agent: Option<&AgentPlan>,
181	    visibility: &str,
182	) -> String {
183	    let (url, slug, bare) = match agent {
184	        Some(a) => (a.url.as_str(), a.gh_slug.as_deref(), a.bare_path.as_ref()),
185	        None => (
186	            plan.work_url.as_str(),
187	            plan.gh_work_slug.as_deref(),
188	            plan.work_bare_path.as_ref(),
189	        ),
190	    };
191	    let remote = match (&plan.provisioner, slug, bare) {
192	        (Provisioner::GhCreate, Some(slug), _) => format!("create GitHub repo {slug} {visibility}"),
193	        (Provisioner::LocalBareInit, _, Some(bare)) => {
194	            format!("create bare repo {}", bare.display())
195	        }
196	        _ => "use the existing remote".to_string(),
197	    };
198	    format!("Set main on the {side} repo's initial commit, {remote}, and push to {url}")
199	}
