//! Flat plain-struct input to the init op.
//!
//! `InitParams` is the clap-free shape that `pub fn init` reads
//! from. Built `From<&InitArgs>` at the binary edge (main.rs);
//! callers without clap (tests, future TUI / library embedding)
//! construct it directly.
//!
//! Per `notes/chores/chores-09.md > ## InitParams implementation
//! (0.44.0)`: domain types pass through (`RepoSelector`,
//! `ConfigKind`, `PushRetryOptions`); leaf clap wrappers do not.

use crate::config::RepoSelector;
use crate::init::InitArgs;
use crate::options_flags::config::ConfigKind;
use crate::options_flags::push_retry::PushRetryOptions;

/// Inputs to the init op, flat, owned, clap-free.
///
/// - `target`: `--target` (URL, path, or
///   bare NAME).
/// - `name`: optional `--name` override.
/// - `account`: `--account` value (None => default account chain).
/// - `repo`: `--repo` value parsed into a `RepoSelector`.
/// - `test_remotes`: `--test-repo`, the directory its bare remotes,
///   named by the repo, go in, in place of the `--repo` chain.
/// - `por`: `-s` resolved, `true` for `por`, a plain single repo,
///   `false` (default) for dual workspace.
/// - `private`: `--private`.
/// - `dry_run`: `--dry-run`.
/// - `push_retry`: `--push-retries` / `--push-retry-delay`.
/// - `config`: resolved `--config` value (None => canned write).
/// - `adopt`: `--adopt`, convert an existing target.
/// - `upstream`: `--upstream`, the name an adopted test repo's old
///   `origin` is kept under, None removing it.
/// - `agent_dir`, `agent_repo`, `agent_suffix`: the `--agent-*`
///   flags, None meaning the default (dual only).
/// - `create_symlink`: whether `init` should create the
///   `~/.claude/projects/` symlink for dual runs (production
///   path = true; test fixtures suppress with false).
pub struct InitParams {
    pub target: String,
    pub name: Option<String>,
    pub account: Option<String>,
    pub repo: Option<RepoSelector>,
    pub test_remotes: Option<String>,
    pub por: bool,
    pub private: bool,
    pub dry_run: bool,
    pub push_retry: PushRetryOptions,
    pub config: Option<ConfigKind>,
    pub adopt: bool,
    pub upstream: Option<String>,
    pub no_url_trailer: bool,
    pub agent_dir: Option<String>,
    pub agent_repo: Option<String>,
    pub agent_suffix: Option<String>,
    pub create_symlink: bool,
}

impl From<&InitArgs> for InitParams {
    /// Convert clap-derived `InitArgs` into the flat `InitParams`.
    ///
    /// Production path: sets `create_symlink: true`. Tests that
    /// need `create_symlink: false` construct `InitParams`
    /// directly (or post-edit the field).
    fn from(a: &InitArgs) -> Self {
        Self {
            // OK: clap requires TARGET unless the retired --target was
            // given, and `to_params` refuses that first
            target: a.target.clone().unwrap_or_default(),
            name: a.name.clone(),
            account: a.account.value.clone(),
            repo: a.repo.value.clone(),
            test_remotes: a.test_repo.clone(),
            por: a.por.is_por(),
            private: a.provision.private.value,
            dry_run: a.provision.dry_run.value,
            push_retry: a.provision.push_retry.clone(),
            config: a.config.resolve(ConfigKind::None),
            adopt: a.adopt,
            upstream: a.upstream.clone(),
            no_url_trailer: a.no_url_trailer,
            agent_dir: a.agent_dir.clone(),
            agent_repo: a.agent_repo.clone(),
            agent_suffix: a.agent_suffix.clone(),
            create_symlink: true,
        }
    }
}

/// CLI args for `vc-x1 init`.
#[derive(Args, Debug)]
pub struct InitArgs {
    /// What to create: URL, path, or bare NAME, the one positional.
    ///
    /// - URL: `git@host:owner/name(.git)?`, `https://...(.git)?`,
    ///   used as-is, config not consulted.
    /// - Path: `./X`, `../X`, `/X`, `~/X`, `~`, `.`, `..`, is the
    ///   directory path, remote resolved via `--repo` chain.
    /// - Bare NAME: becomes NAME.git, remote resolved via
    ///   `--repo` chain.
    ///
    /// A slashed target with no path prefix (`owner/name`) is
    /// refused: it reads equally as a path and as the retired
    /// owner/name shorthand, so pass `./owner/name` or a URL.
    #[arg(
        value_name = "TARGET",
        value_hint = ValueHint::AnyPath,
        required_unless_present = "target_flag",
        verbatim_doc_comment
    )]
    pub target: Option<String>,

    /// Retired: a second positional, the old `TARGET NAME`, refused
    /// naming `--name`.
    #[arg(value_name = "RETIRED", hide = true, num_args = 0..)]
    pub retired: Vec<String>,

    /// Retired: `--target`, the target positional now, refused naming it.
    #[arg(long = "target", value_name = "TARGET", hide = true)]
    pub target_flag: Option<String>,

    /// Make the target a throwaway test repo, its bare remotes in
    /// REMOTES, so nothing leaves this machine.
    ///
    /// The remotes are named by the repo, `<name>.git` and
    /// `<name>.agent-session.git`, so several test repos share one
    /// REMOTES, and a name already there is refused. REMOTES is
    /// always a path, so `tmp/remotes` needs no `./`. Not with a URL
    /// target, or what names a remote. With `--adopt` the target
    /// is an existing repo or directory, an origin it has replaced by
    /// REMOTES and kept only by `--upstream`.
    #[arg(
        long = "test-repo",
        value_name = "REMOTES",
        value_hint = ValueHint::AnyPath,
        verbatim_doc_comment
    )]
    pub test_repo: Option<String>,

    /// Repo directory name override (URL form only).
    ///
    /// - URL form: repo created at `cwd/<NAME>` instead of the
    ///   URL-derived name.
    /// - Path / bare-NAME forms: error if given (TARGET already
    ///   names the repo).
    #[arg(long = "name", value_name = "NAME", verbatim_doc_comment)]
    pub name: Option<String>,

    /// `--account`: flatten of the shared [`AccountOption`] leaf.
    #[command(flatten)]
    pub account: AccountOption,

    /// `--repo`: flatten of the shared [`RepoOption`] leaf.
    /// Init's built-in categories: `remote` (a URL prefix init
    /// appends `/<NAME>.git` to) and `local` (parent dir for
    /// fixture bare repos). Meaningful only with Path or
