impl InitArgs {
    /// Refuse what `--test-repo` cannot mean: a URL, as its value or
    /// the target's, since nothing leaves the machine, and the flags
    /// that name another remote, an existing directory, or a publish.
    fn check_test_repo(&self) -> Result<(), String> {
        let Some(path) = &self.test_repo else {
            return Ok(());
        };
        for (set, flag) in [
            (self.name.is_some(), "--name"),
            (self.account.value.is_some(), "--account"),
            (self.repo.value.is_some(), "--repo"),
            (self.provision.private.value, "--private"),
        ] {
            if set {
                return Err(format!(
                    "{flag} is not taken with --test-repo: its remotes are in REMOTES, and \
                     nothing leaves this machine"
                ));
            }
        }
        // Only a URL is refused: `tmp/remotes`, ambiguous as a target, is
        // a path here, since a test repo's remotes are never on GitHub.
        if let Ok(Target::Url(_)) = parse_target(path) {
            return Err(format!(
                "--test-repo takes a path, and '{path}' is a URL: nothing leaves this machine"
            ));
        }
        if let Some(target) = &self.target
            && let Ok(Target::Url(_)) = parse_target(target)
        {
            return Err(format!(
                "the target '{target}' is a URL, and a test repo is a path: nothing leaves this \
                 machine"
            ));
        }
        Ok(())
    }
}

impl SubcommandRunner for InitArgs {
    type Params = InitParams;

    /// Refuse the retired positionals and `--por`, else delegate to
    /// the `From<&InitArgs>` impl in [`crate::init::params`].
    fn to_params(&self) -> Result<Self::Params, String> {
        if let Some(t) = &self.target_flag {
            return Err(format!(
                "init --target: the target is positional now: `vc-x1 init {t}`"
            ));
        }
        if let Some(name) = self.retired.first() {
            return Err(format!(
                "init: the one positional is the TARGET, and '{name}' is a second: the directory \
                 name is `--name {name}`"
            ));
        }
        self.por.check("init")?;
        self.check_test_repo()?;
        Ok(InitParams::from(self))
    }

    /// Run the existing `init` op.
    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        init(ctx, params)
    }
}

/// Init entry point: runs the dual or POR provisioning flow.
///
/// Takes the shared `Context` (loaded user config) and the flat
/// `InitParams`. CLI builds both at the binary edge in main.rs,
/// and tests construct `InitParams` directly.
///
/// `params.create_symlink` controls the `~/.claude/projects/`
/// symlink side effect:
///
/// - `true`: CLI behavior, where step 11 creates the symlink for
///   dual-scope runs.
/// - `false`: suppresses that side effect, used by test
///   harnesses (`test_helpers::Fixture`, `test_helpers::FixturePor`)
///   so parallel fixtures don't collide on the user's home dir.
pub fn init(ctx: &Context, params: &InitParams) -> Result<(), Box<dyn std::error::Error>> {
    debug!("init: enter");

    let create_symlink = params.create_symlink;
    let cfg = &ctx.user_config;
    let mut plan = plan_init(params, cfg)?;
    let state = adopt::detect_target_state(&plan.project_dir)?;
    debug!("init: target is {state:?}");

    // --- Preflight ---
    info!("Preflight checks...");

    check_target_state(&plan.project_dir, &state, params.adopt)?;
    let adopting_repo = matches!(
        state,
        adopt::TargetState::Por | adopt::TargetState::SingleRepo
    );
    let git_only = adopting_repo && adopt::is_git_only(&plan.project_dir);
    if adopting_repo {
        adopt::check_colocation(&plan.project_dir)?;
        // A git-only repo's working copy is read once jj colocates it.
        if !git_only {
            adopt::check_clean(&plan.project_dir)?;
        }
        plan_existing_repo(&mut plan, params, state == adopt::TargetState::SingleRepo)?;
    }
    if let Some(e) = &plan.remote_error {
        return Err(format!("{e} (the target has no origin to take the remotes from)").into());
    }

    // No "is jj installed" probe: init runs through
    // jj-lib, and main's version gate already errored out on a
    // missing or mismatched jj CLI before dispatch.
    if plan.provisioner == Provisioner::GhCreate {
        debug!("verify gh CLI is installed + authenticated");
        gh(&["auth", "status"], Path::new("."))
            .map_err(|_| "gh is not installed or not authenticated (run: gh auth login)")?;
    }
    if let Some(agent) = &plan.agent
        && agent.path.exists()
    {
        return Err(format!(
            "'{}' already exists: name another agent directory with --agent-dir",
            agent.path.display()
        )
        .into());
    }

    match &plan.provisioner {
        Provisioner::GhCreate => {
            // An adopted repo's own origin has no slug to check: it
            // exists already, and nothing creates it.
            if let Some(work_slug) = plan.gh_work_slug.as_ref() {
                let (work_owner, work_name) = split_slug(work_slug)?;
                if gh_repo_exists(work_owner, work_name)? {
                    return Err(format!("GitHub repo '{work_slug}' already exists").into());
                }
            }
            if let Some(bot_slug) = plan.agent.as_ref().and_then(|a| a.gh_slug.as_ref()) {
                let (bot_owner, bot_name) = split_slug(bot_slug)?;
                if gh_repo_exists(bot_owner, bot_name)? {
                    return Err(format!("GitHub repo '{bot_slug}' already exists").into());
                }
            }
        }
        Provisioner::LocalBareInit => {
            if let Some(work_bare) = plan.work_bare_path.as_ref()
                && work_bare.exists()
            {
                return Err(format!(
                    "bare repo '{}' already exists; refusing to clobber",
                    work_bare.display()
                )
                .into());
            }
            if let Some(bot_bare) = plan.agent.as_ref().and_then(|a| a.bare_path.as_ref())
                && bot_bare.exists()
            {
                return Err(format!(
                    "bare repo '{}' already exists; refusing to clobber",
                    bot_bare.display()
                )
                .into());
            }
        }
        Provisioner::ExternalPreExisting => {
            // For path-shaped URLs: the path must exist (caller
            // pre-created with `git init --bare`). For scheme-URL
            // values we can't preflight cheaply, let git push
            // surface failures.
            if !is_remote_url(&plan.work_url) {
                let p = PathBuf::from(&plan.work_url);
                if !p.exists() {
                    return Err(format!(
                        "--repo-remote: work path '{}' does not exist, \
                         pre-create with `git init --bare`, or use --repo-local for \
                         fixture creation",
                        p.display()
                    )
                    .into());
                }
            }
            if let Some(bot_url) = plan.agent.as_ref().map(|a| &a.url)
                && !is_remote_url(bot_url)
            {
                let p = PathBuf::from(bot_url);
                if !p.exists() {
                    return Err(format!(
                        "--repo-remote: bot path '{}' does not exist, \
                         pre-create with `git init --bare`, or use --repo-local for \
                         fixture creation",
                        p.display()
                    )
                    .into());
                }
            }
        }
    }

    let visibility = if params.private {
        "--private"
    } else {
        "--public"
    };

    let steps = steps::Steps::new(&plan, params, visibility, create_symlink);
    if params.dry_run {
        if params.adopt {
            info!(
                "Dry run, adopting {}, {}, would execute:",
                plan.project_dir.display(),
                state.describe()
            );
        } else {
            info!("Dry run, would execute:");
        }
        steps.print_all();
        return Ok(());
    }

    if git_only {
        steps.begin(steps::Step::Colocate);
        adopt::colocate(&plan.project_dir)?;
    }
    if let Err(e) = check_adopted(&plan, git_only) {
        if git_only {
            undo_colocation(&plan.project_dir);
        }
        return Err(e);
    }

    match &plan.agent {
        None => create_por(params, &plan, &steps, visibility),
        Some(agent) => create_dual(params, &plan, agent, &steps, visibility),
    }
}

/// The checks an adopted repo takes once jj can read it, before
/// anything is written: a git-only repo's clean working copy, and an
/// agent remote init does not create, which must exist.
///
/// The remote is asked for its heads, so one that does not exist, or
/// cannot be reached, is refused here and not at the push, after the
/// work repo was committed and the agent repo made.
fn check_adopted(plan: &InitPlan, git_only: bool) -> Result<(), Box<dyn std::error::Error>> {
    if !matches!(plan.work_start, WorkStart::Repo { .. }) {
        return Ok(());
    }
    if git_only {
        adopt::check_clean(&plan.project_dir)?;
    }
    if plan.provisioner == Provisioner::ExternalPreExisting
        && let Some(agent) = &plan.agent
        && is_remote_url(&agent.url)
        && let Err(e) = jj::git_ls_remote_heads(&plan.project_dir, &agent.url)
    {
        return Err(format!(
            "--adopt: the agent repo's remote {} does not exist or cannot be reached, and init \
             creates a remote only on GitHub or as a path: create it first ({e})",
            agent.url
        )
        .into());
    }
    Ok(())
}

/// Take back the colocation of a git-only repo whose adopt was then
/// refused, so a refusal leaves the repo as it was found. The `.jj`
/// directory is init's own, made moments before.
fn undo_colocation(dir: &Path) {
    if let Err(e) = std::fs::remove_dir_all(dir.join(".jj")) {
        warn!(
            "could not remove {}, made by this run: {e}",
            dir.join(".jj").display()
        );
    }
}

/// Create-from-empty orchestrator for `-s por` (single repo).
///
/// Composes (in order):
/// - `prepare_local_repo` -> conditional `.vc-config.md` write
///   (gated by `--config`) -> `write_por_gitignore` (always) ->
///   `write_record_files` -> `commit_initial` (`OchidStrategy::None`).
/// - `push_repo` for work side (no `clean_exclude`).
/// - No cross-reference (no bot repo), no bot push, no symlink.
///
/// `steps` numbers and titles each step as it starts.
fn create_por(
    params: &InitParams,
    plan: &InitPlan,
    steps: &steps::Steps,
    visibility: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    use steps::Step;

    steps.begin(Step::PrepareWork);
    prepare_local_repo(&plan.project_dir, "work")?;
    steps.begin(Step::ConfigWork);
    match &params.config {
        None => write_por_vc_config(&plan.project_dir)?,
        Some(ConfigKind::None) => {} // skip, user asked not to write
        Some(ConfigKind::Path(p)) => copy_user_config(p, &plan.project_dir)?,
    }
    write_por_gitignore(&plan.project_dir)?;
    write_record_files(&plan.project_dir)?;
    steps.begin(Step::CommitWork);
    let work_chid = commit_initial(
        &plan.project_dir,
        "work",
        INITIAL_TITLE,
        OchidStrategy::None,
    )?;
    // Colocated, so the jj commit id is the git hash.
    let hash = jj::cid_of(&plan.project_dir, "@-")?;
    debug!("work repo: chid={work_chid} hash={hash}");

    steps.begin(Step::PublishWork);
    let work_chid_final = push_repo(
        &plan.project_dir,
        "work",
        plan,
        params,
        visibility,
        &plan.work_url,
        plan.gh_work_slug.as_deref(),
        plan.work_bare_path.as_deref(),
    )?;

    info!("");
    info!("Done! Project created at {}", plan.project_dir.display());
    info!(
        "  Work repo:    {}  (chid={work_chid_final})",
        plan.work_url
    );

    debug!("init: exit");
    Ok(())
}

/// Create-from-empty orchestrator for the default dual shape.
///
/// Composes (in order):
/// - Work side: `prepare_local_repo` -> `write_work_config` ->
///   `write_record_files` -> `commit_initial`
///   (`OchidStrategy::Placeholder`).
/// - Bot side: `prepare_local_repo` -> `write_bot_config`
///   -> `commit_initial` (`OchidStrategy::Placeholder`).
/// - `cross_ref_ochids`: rewrite both initial commits' placeholder
///   trailers once each side's chid is known.
/// - `push_repo` for bot side (no `clean_exclude`).
/// - `push_repo` for work side.
/// - `symlink::install` (when `create_symlink`).
fn create_dual(
    params: &InitParams,
    plan: &InitPlan,
    agent: &AgentPlan,
    steps: &steps::Steps,
    visibility: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    use steps::Step;

    // An adopted repo is prepared already, and keeps its history: its
    // commit goes on top of it under a title of its own.
    let work_title = match plan.work_start {
        WorkStart::Fresh => {
            steps.begin(Step::PrepareWork);
            prepare_local_repo(&plan.project_dir, "work")?;
            INITIAL_TITLE
        }
        WorkStart::Repo { .. } => ADOPT_TITLE,
    };
    steps.begin(Step::ConfigWork);
    // The recorded name is the agent-repo's *remote* name, the last
    // segment of its origin URL, which need not follow the project's
    // name: a fixture whose bare is `remote-work.agent-session.git` under
    // a project called `tr` shows the two diverging.
    let agent_repo = derive_name(&agent.url)?;
    if let WorkStart::Repo {
        has_config: true, ..
    } = plan.work_start
    {
        adopt::add_agent_to_config(&plan.project_dir, &agent.dir, &agent_repo)?;
        write_work_gitignore(&plan.project_dir, &agent.dir)?;
    } else {
        write_work_config(&plan.project_dir, &agent.dir, &agent_repo)?;
    }
    write_record_files(&plan.project_dir)?;
    steps.begin(Step::CommitWork);
    let work_chid = commit_initial(
        &plan.project_dir,
        "work",
        work_title,
        OchidStrategy::Placeholder,
    )?;

    steps.begin(Step::PrepareAgent);
    prepare_local_repo(&agent.path, "agent")?;
    steps.begin(Step::ConfigAgent);
    write_bot_config(&agent.path)?;
    steps.begin(Step::CommitAgent);
    let agent_chid = commit_initial(
        &agent.path,
        "agent",
        INITIAL_TITLE,
        OchidStrategy::Placeholder,
    )?;

    steps.begin(Step::CrossLink);
    let trailer_url = |url| (!params.no_url_trailer).then_some(url);
    cross_ref_ochids(
        CrossRefSide {
            dir: &plan.project_dir,
            url: trailer_url(plan.work_url.as_str()),
            chid: &work_chid,
        },
        work_title,
        CrossRefSide {
            dir: &agent.path,
            url: trailer_url(agent.url.as_str()),
            chid: &agent_chid,
        },
    )?;

    steps.begin(Step::PublishAgent);
    let agent_chid_final = push_repo(
        &agent.path,
        "agent",
        plan,
        params,
        visibility,
        &agent.url,
        agent.gh_slug.as_deref(),
        agent.bare_path.as_deref(),
    )?;
    // An adopted repo with an origin publishes nothing: its commit is
    // the user's to land, as any change of theirs is.
    let work_chid_final = if plan.work_start.keeps_its_origin() {
        jj::chid_of(&plan.project_dir, "@-")?
    } else {
        if plan.replaced_origin.is_some() {
            steps.begin(Step::ReplaceOrigin);
            match &params.upstream {
                Some(name) => jj::git_remote_rename(&plan.project_dir, "origin", name)?,
                None => jj::git_remote_remove(&plan.project_dir, "origin")?,
            }
        }
        steps.begin(Step::PublishWork);
        push_repo(
            &plan.project_dir,
            "work",
            plan,
            params,
            visibility,
            &plan.work_url,
            plan.gh_work_slug.as_deref(),
            plan.work_bare_path.as_deref(),
        )?
    };

    let sl_opt = if params.create_symlink {
        steps.begin(Step::Symlink);
        Some(symlink::install(&plan.project_dir)?)
    } else {
        None
    };

    info!("");
    info!("Done! Project created at {}", plan.project_dir.display());
    info!(
        "  Work repo:    {}  (chid={work_chid_final})",
        plan.work_url
    );
    info!("  Agent repo:   {}  (chid={agent_chid_final})", agent.url);
    if let Some(sl) = sl_opt.as_ref() {
        info!(
            "  Symlink:      {} -> {}",
            sl.symlink_path.display(),
            sl.abs_target.display()
        );
    }

    debug!("init: exit");
    Ok(())
}

