673	    let work = base.join("work");
674	    std::fs::create_dir_all(work.join("pins")).unwrap();
675	    std::fs::write(work.join("notes.txt"), "a record\n").unwrap();
676	    // Over jj's 1MiB new-file limit, which a plain snapshot skips.
677	    std::fs::write(
678	        work.join("pins").join("big.jsonl"),
679	        vec![b'x'; 2 * 1024 * 1024],
680	    )
681	    .unwrap();
682	    std::fs::write(work.join(".gitignore"), "*.log").unwrap();
683	    std::fs::write(work.join("run.log"), "noise\n").unwrap();
684	    std::fs::write(work.join("TODO.md"), "# Its own\n").unwrap();
685	
