1	//! `agent-files copy [SRC] [DST]`: make the set in DST a byte copy
2	//! of the one in SRC, and leave it uncommitted.
3	//!
4	//! - `CopyArgs`: clap surface, the `SRC` and `DST` operands and the
5	//!   `-c`/`--custom` / `--no-custom` pair, as `diff` has them.
6	//! - `plan`: what a copy would do, from `diff::compare`'s rows:
7	//!   copy what differs or is only in SRC, delete what is only in
8	//!   DST, and never touch custom.md unless asked, or TODO.md at
9	//!   all.
10	//! - `apply`: do it. The jj working copy around DST must be clean
11	//!   in the set's paths first, so the copy's changes are the only
12	//!   ones there and a `jj diff` reads as the re-sync.
13	
14	use std::path::{Path, PathBuf};
15	use std::process::ExitCode;
16	
17	use clap::Args;
18	use log::{error, info};
19	
20	use super::diff::{self, AGENT_DATA, State};
21	use crate::common;
22	
23	/// CLI args for `agent-files copy`.
24	#[derive(Args, Debug)]
25	pub struct CopyArgs {
26	    /// Retired: the two directories, now `--from` and `--to`, refused
27	    /// naming them.
28	    #[arg(value_name = "RETIRED", hide = true, num_args = 0..=2)]
29	    pub retired: Vec<String>,
30	
31	    /// The directory to copy the set from [default:
32	    /// agent-files.copy.dir, else family.template, else an error]
33	    #[arg(long = "from", value_name = "DIR")]
34	    pub src: Option<PathBuf>,
35	
36	    /// The directory whose set becomes the copy [default: this
37	    /// workspace, so one side is --from]
38	    #[arg(long = "to", value_name = "DIR")]
39	    pub dst: Option<PathBuf>,
40	
41	    /// Copy custom.md with the rest of the set
42	    #[arg(short = 'c', long = "custom", conflicts_with = "no_custom")]
43	    pub custom: bool,
44	
45	    /// Leave custom.md alone, overriding agent-files.copy.custom
46	    #[arg(long = "no-custom")]
47	    pub no_custom: bool,
48	}
49	
50	/// One step of a copy.
51	#[derive(Debug, Clone, PartialEq, Eq)]
52	pub enum Step {
53	    Copy(String),
54	    Delete(String),
55	}
56	
57	impl std::fmt::Display for Step {
58	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
59	        match self {
60	            Step::Copy(p) => write!(f, "copy   {p}"),
61	            Step::Delete(p) => write!(f, "delete {p}"),
62	        }
63	    }
64	}
65	
66	/// The steps that make `dst`'s set equal to `src`'s, in path
67	/// order: a copy for each file that differs or exists only in
68	/// `src`, a delete for each that exists only in `dst`. Nothing for
69	/// the project layer when it is not asked for.
70	pub fn plan(src: &Path, dst: &Path, custom: bool) -> Result<Vec<Step>, Box<dyn std::error::Error>> {
71	    Ok(diff::compare(src, dst, custom)?
72	        .into_iter()
73	        .filter_map(|(path, state)| match state {
74	            State::Differs | State::OnlyInA => Some(Step::Copy(path)),
75	            State::OnlyInB => Some(Step::Delete(path)),
76	            State::Same | State::ProjectLayer => None,
77	        })
78	        .collect())
79	}
80	
81	/// Run the steps: copy creates `agent-data/` when it is missing,
82	/// delete removes the file only.
83	pub fn apply(src: &Path, dst: &Path, steps: &[Step]) -> Result<(), Box<dyn std::error::Error>> {
84	    for step in steps {
85	        match step {
86	            Step::Copy(path) => {
87	                if let Some(parent) = dst.join(path).parent() {
88	                    std::fs::create_dir_all(parent)?;
89	                }
90	                std::fs::copy(src.join(path), dst.join(path))
91	                    .map_err(|e| format!("copy {path}: {e}"))?;
92	            }
93	            Step::Delete(path) => {
94	                std::fs::remove_file(dst.join(path)).map_err(|e| format!("delete {path}: {e}"))?;
95	            }
96	        }
97	    }
98	    Ok(())
99	}
100	
101	/// True when `path`, relative to a set directory, is one the copy
102	/// may touch: AGENTS.md, anything under `agent-data/`, and
103	/// custom.md when `custom`.
104	fn in_set(path: &str, custom: bool) -> bool {
105	    path == diff::AGENTS_MD
106	        || path.starts_with(&format!("{AGENT_DATA}/"))
107	        || (custom && path == diff::CUSTOM_MD)
108	}
109	
110	/// The changed paths inside `dst`'s set in the jj working copy
111	/// around it, which a copy would mix its own changes with. `None`
112	/// when `dst` is not inside a jj repo. `dst` may be a subdirectory
113	/// of the repo, the payload inside the template repo being one, so
114	/// the repo's paths are matched under `dst`'s prefix.
115	fn dirty_set_paths(
116	    dst: &Path,
117	    custom: bool,
118	) -> Result<Option<Vec<String>>, Box<dyn std::error::Error>> {
119	    let dst = dst.canonicalize()?;
120	    let Some(repo) = crate::status::nearest_jj(&dst) else {
121	        return Ok(None);
122	    };
123	    let repo = repo.canonicalize()?;
124	    let prefix = dst
125	        .strip_prefix(&repo)
126	        .map(|p| p.to_string_lossy().into_owned())
127	        .unwrap_or_default();
128	    let prefix = if prefix.is_empty() {
129	        prefix
130	    } else {
131	        format!("{prefix}/")
132	    };
133	    Ok(Some(
134	        crate::jj::wc_status(&repo)?
135	            .changes
136	            .into_iter()
137	            .filter_map(|(letter, p)| {
138	                p.strip_prefix(&prefix)
139	                    .filter(|rel| in_set(rel, custom))
140	                    .map(|_| format!("{letter} {p}"))
141	            })
142	            .collect(),
143	    ))
144	}
145	
146	impl CopyArgs {
147	    /// Run the copy.
148	    pub fn run(&self) -> ExitCode {
149	        match self.copy() {
150	            Ok(()) => ExitCode::SUCCESS,
151	            Err(e) => {
152	                error!("agent-files copy: {e}");
153	                ExitCode::FAILURE
154	            }
155	        }
156	    }
157	
158	    /// Resolve, guard, print the plan, apply it.
159	    fn copy(&self) -> Result<(), Box<dyn std::error::Error>> {
160	        diff::refuse_from_to("agent-files copy", &self.retired)?;
161	        let root = common::find_workspace_root();
162	        let cfg = match &root {
163	            Some(r) => super::config_at(r)?,
164	            None => super::WorkspaceAgentFiles::default(),
165	        };
166	        let template = match &root {
167	            Some(r) => diff::family_template(r)?,
168	            None => None,
169	        };
170	        let src = diff::resolve_set_dir(
171	            root.as_deref(),
172	            self.src.as_deref(),
173	            "agent-files.copy.dir",
174	            cfg.copy.dir.as_deref(),
175	            template.as_deref(),
176	        )?;
177	        let dst = diff::resolve_here(root.as_deref(), self.dst.as_deref())?;
178	        let custom = diff::resolve_custom(
179	            self.custom,
180	            self.no_custom,
181	            cfg.copy.custom,
182	            crate::config_schema::AGENT_FILES_COPY_CUSTOM_DEFAULT,
183	        );
184	        if src.path.canonicalize()? == dst.path.canonicalize()? {
185	            return Err(
186	                format!("'{}' and '{}' are the same directory", src.shown, dst.shown).into(),
187	            );
188	        }
189	        info!(
190	            "agent-files copy: from {} ({}) into {} ({}){}",
191	            src.shown,
192	            src.source,
193	            dst.shown,
194	            dst.source,
195	            if custom { ", custom.md included" } else { "" }
196	        );
197	        match dirty_set_paths(&dst.path, custom)? {
198	            None => info!("{} is not in a jj repo: no working-copy guard", dst.shown),
199	            Some(dirty) if !dirty.is_empty() => {
200	                return Err(format!(
201	                    "the working copy around '{}' already changes the set, commit or restore \
202	                     first:\n  {}",
203	                    dst.shown,
204	                    dirty.join("\n  ")
205	                )
206	                .into());
207	            }
208	            Some(_) => {}
209	        }
210	        let steps = plan(&src.path, &dst.path, custom)?;
211	        if steps.is_empty() {
212	            info!("already the same, nothing to do");
213	            return Ok(());
214	        }
215	        for step in &steps {
216	            info!("{step}");
217	        }
218	        apply(&src.path, &dst.path, &steps)?;
219	        info!(
220	            "{} step(s) applied, left uncommitted for review",
221	            steps.len()
222	        );
223	        Ok(())
224	    }
225	}
