266	    /// A copy plan copies what differs or is only in the source,
267	    /// deletes what is only in the destination, and leaves custom.md
268	    /// and TODO.md alone until `-c` brings custom.md in. Applied,
269	    /// the sets compare equal.
270	    #[test]
271	    fn plan_and_apply_mirror_the_set() {
272	        let base = crate::test_helpers::unique_base("af-copy");
273	        let src = base.join("src");
274	        let dst = base.join("dst");
275	        seed(
276	            &src,
277	            &[
278	                ("AGENTS.md", "new rules\n"),
279	                ("custom.md", "theirs\n"),
280	                ("TODO.md", "their todo\n"),
281	                ("agent-data/a.md", "same\n"),
282	                ("agent-data/b.md", "new\n"),
283	            ],
284	        );
285	        seed(
286	            &dst,
287	            &[
288	                ("AGENTS.md", "old rules\n"),
289	                ("custom.md", "mine\n"),
290	                ("TODO.md", "my todo\n"),
291	                ("agent-data/a.md", "same\n"),
292	                ("agent-data/stale.md", "gone\n"),
293	            ],
294	        );
295	        let steps = plan(&src, &dst, false).unwrap();
296	        assert_eq!(
297	            steps,
298	            vec![
299	                Step::Copy("AGENTS.md".to_string()),
300	                Step::Copy("agent-data/b.md".to_string()),
301	                Step::Delete("agent-data/stale.md".to_string()),
302	            ]
303	        );
304	        assert_eq!(steps[0].to_string(), "copy   AGENTS.md");
305	        assert_eq!(steps[2].to_string(), "delete agent-data/stale.md");
306	        apply(&src, &dst, &steps).unwrap();
307	        let rows = diff::compare(&src, &dst, false).unwrap();
308	        assert!(rows.iter().all(|(_, s)| !s.differs()), "{rows:?}");
309	        assert_eq!(
310	            std::fs::read_to_string(dst.join("custom.md")).unwrap(),
311	            "mine\n"
312	        );
313	        assert_eq!(
314	            std::fs::read_to_string(dst.join("TODO.md")).unwrap(),
315	            "my todo\n"
316	        );
317	        assert!(plan(&src, &dst, false).unwrap().is_empty());
318	        let steps = plan(&src, &dst, true).unwrap();
319	        assert_eq!(steps, vec![Step::Copy("custom.md".to_string())]);
320	        apply(&src, &dst, &steps).unwrap();
