1	//! `agent-files diff [A] [B]`: which files of two copies of the set
2	//! differ, one line per file, names only.
3	//!
4	//! - `DiffArgs`: clap surface, the `A` and `B` operands and the
5	//!   `-c`/`--custom` / `--no-custom` pair.
6	//! - `resolve_set_dir`: `A` as given, else the command's `dir`
7	//!   key, else `family.template`, relative paths against the
8	//!   config file's directory. `B` as given, else the workspace
9	//!   around the current directory. Shared with `copy`, where the
10	//!   same pair is its source and destination.
11	//! - `resolve_custom`: the flag, else the command's `custom` key,
12	//!   else the built-in.
13	//! - `compare`: the union of both sides' set files with each one's
14	//!   state, and `report` renders it. The exit status is non-zero
15	//!   when anything differs, as `diff`'s is, so a script can ask
16	//!   "is a re-sync a copy?" without reading.
17	
18	use std::collections::BTreeSet;
19	use std::path::{Path, PathBuf};
20	use std::process::ExitCode;
21	
22	use clap::Args;
23	use log::{error, info};
24	
25	use crate::common;
26	
27	/// The set's fixed members beside `agent-data/`.
28	pub const AGENTS_MD: &str = "AGENTS.md";
29	/// The project layer, compared only on request.
30	pub const CUSTOM_MD: &str = "custom.md";
31	/// The directory whose files are the rest of the set.
32	pub const AGENT_DATA: &str = "agent-data";
33	
34	/// CLI args for `agent-files diff`.
35	#[derive(Args, Debug)]
36	pub struct DiffArgs {
37	    /// Retired: the two directories, now `--from` and `--to`, refused
38	    /// naming them.
39	    #[arg(value_name = "RETIRED", hide = true, num_args = 0..=2)]
40	    pub retired: Vec<String>,
41	
42	    /// A directory holding a copy of the set [default:
43	    /// agent-files.diff.dir, else family.template, else an error]
44	    #[arg(long = "from", value_name = "DIR")]
45	    pub a: Option<PathBuf>,
46	
47	    /// The other copy [default: this workspace, so one side is --from]
48	    #[arg(long = "to", value_name = "DIR")]
49	    pub b: Option<PathBuf>,
50	
51	    /// Compare custom.md like the rest of the set
52	    #[arg(short = 'c', long = "custom", conflicts_with = "no_custom")]
53	    pub custom: bool,
54	
55	    /// Leave custom.md out, overriding agent-files.diff.custom
56	    #[arg(long = "no-custom")]
57	    pub no_custom: bool,
58	}
59	
60	/// One file's state across the two sides.
61	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
62	pub enum State {
63	    Same,
64	    Differs,
65	    OnlyInA,
66	    OnlyInB,
67	    /// custom.md when it is not compared: the project layer.
68	    ProjectLayer,
69	}
70	
71	impl State {
72	    /// True when the state is a difference a copy would change.
73	    pub fn differs(self) -> bool {
74	        matches!(self, State::Differs | State::OnlyInA | State::OnlyInB)
75	    }
76	
77	    fn label(self, a: &str, b: &str) -> String {
78	        match self {
79	            State::Same => "same".to_string(),
80	            State::Differs => "differs".to_string(),
81	            State::OnlyInA => format!("only in {a}"),
82	            State::OnlyInB => format!("only in {b}"),
83	            State::ProjectLayer => "project layer, not compared (-c compares it)".to_string(),
84	        }
85	    }
86	}
87	
88	/// Where a set directory came from, for the header line.
89	#[derive(Debug, PartialEq, Eq)]
90	pub enum DirSource {
91	    Operand,
92	    ConfigKey(&'static str),
93	    FamilyTemplate,
94	    Workspace,
95	}
96	
97	impl std::fmt::Display for DirSource {
98	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
99	        match self {
100	            DirSource::Operand => write!(f, "the operand"),
101	            DirSource::ConfigKey(k) => write!(f, "{k}"),
102	            DirSource::FamilyTemplate => write!(f, "family.template"),
103	            DirSource::Workspace => write!(f, "this workspace"),
104	        }
105	    }
106	}
107	
108	/// A resolved set directory: the path to use, the text it was
109	/// written as, for the report, and where it came from.
110	#[derive(Debug, PartialEq, Eq)]
111	pub struct SetDir {
112	    pub path: PathBuf,
113	    pub shown: String,
114	    pub source: DirSource,
115	}
116	
117	impl SetDir {
118	    fn new(
119	        path: PathBuf,
120	        shown: String,
121	        source: DirSource,
122	    ) -> Result<Self, Box<dyn std::error::Error>> {
123	        if !path.is_dir() {
124	            return Err(format!("set directory '{shown}' ({source}) is not a directory").into());
125	        }
126	        Ok(SetDir {
127	            path,
128	            shown,
129	            source,
130	        })
131	    }
132	}
133	
134	/// The first set directory, `A` for diff and the source for copy:
135	/// the operand as given, else the command's `dir` key, else
136	/// `family.template`, the config values relative to `root`, the
137	/// config file's directory, which is only needed when the operand
138	/// is absent. An error names the three when none is set, and the
139	/// path when the directory is missing.
140	pub fn resolve_set_dir(
141	    root: Option<&Path>,
142	    operand: Option<&Path>,
143	    key: &'static str,
144	    key_value: Option<&str>,
145	    template: Option<&str>,
146	) -> Result<SetDir, Box<dyn std::error::Error>> {
147	    if let Some(p) = operand {
148	        return SetDir::new(p.to_path_buf(), p.display().to_string(), DirSource::Operand);
149	    }
150	    let root = root.ok_or("not in a vc-x1 workspace, and no directory given")?;
151	    if let Some(v) = key_value {
152	        SetDir::new(
153	            common::resolve_repo_path(root, v),
154	            v.to_string(),
155	            DirSource::ConfigKey(key),
156	        )
157	    } else if let Some(t) = template {
158	        SetDir::new(
159	            common::resolve_repo_path(root, t),
160	            t.to_string(),
161	            DirSource::FamilyTemplate,
162	        )
163	    } else {
164	        Err(
165	            format!("no set directory: give one, or set {key} or family.template in the config")
166	                .into(),
167	        )
168	    }
169	}
170	
171	/// The retired `[A] [B]` or `[SRC] [DST]` positionals of `command`,
172	/// refused naming `--from` and `--to` with the directories in place,
173	/// and nothing to refuse when neither was given.
174	pub fn refuse_from_to(command: &str, retired: &[String]) -> Result<(), String> {
175	    crate::options_flags::retired_positional::refuse_two(command, retired, "--from", "--to")
176	}
177	
178	/// The second set directory, `--to`: the operand as given, else the
179	/// workspace around the current directory.
180	pub fn resolve_here(
181	    root: Option<&Path>,
182	    operand: Option<&Path>,
183	) -> Result<SetDir, Box<dyn std::error::Error>> {
184	    if let Some(p) = operand {
185	        return SetDir::new(p.to_path_buf(), p.display().to_string(), DirSource::Operand);
186	    }
187	    let root = root.ok_or("not in a vc-x1 workspace, and no second directory given")?;
188	    SetDir::new(
189	        root.to_path_buf(),
190	        root.display().to_string(),
191	        DirSource::Workspace,
192	    )
193	}
194	
195	/// The `family.template` value of the config at `root`, if any.
196	pub fn family_template(root: &Path) -> Result<Option<String>, Box<dyn std::error::Error>> {
197	    Ok(crate::config_md::load(root)?
198	        .and_then(|c| crate::toml_simple::toml_get(&c.map, "family.template").cloned()))
199	}
200	
201	/// The custom.md choice: the flags, else the config key, else the
202	/// built-in default.
203	pub fn resolve_custom(flag: bool, no_flag: bool, key_value: Option<bool>, default: bool) -> bool {
204	    if flag {
205	        true
206	    } else if no_flag {
207	        false
208	    } else {
209	        key_value.unwrap_or(default)
210	    }
211	}
212	
213	/// The set's files under `dir`, as relative paths: AGENTS.md, the
214	/// plain files directly under `agent-data/`, and custom.md when
215	/// `custom`. A missing file is simply absent, so an empty
216	/// directory is an empty set.
217	pub fn set_files(dir: &Path, custom: bool) -> BTreeSet<String> {
218	    let mut out = BTreeSet::new();
219	    if dir.join(AGENTS_MD).is_file() {
220	        out.insert(AGENTS_MD.to_string());
221	    }
222	    if custom && dir.join(CUSTOM_MD).is_file() {
223	        out.insert(CUSTOM_MD.to_string());
224	    }
225	    if let Ok(entries) = std::fs::read_dir(dir.join(AGENT_DATA)) {
226	        for e in entries.flatten() {
227	            if e.path().is_file()
228	                && let Some(name) = e.file_name().to_str()
229	            {
230	                out.insert(format!("{AGENT_DATA}/{name}"));
231	            }
232	        }
233	    }
234	    out
235	}
236	
237	/// Every set file on either side with its state, sorted by path.
238	/// custom.md rides along as the project layer when it is not
239	/// compared and either side has it.
240	pub fn compare(
241	    a: &Path,
242	    b: &Path,
243	    custom: bool,
244	) -> Result<Vec<(String, State)>, Box<dyn std::error::Error>> {
245	    let in_a = set_files(a, custom);
246	    let in_b = set_files(b, custom);
247	    let mut out = Vec::new();
248	    for path in in_a.union(&in_b) {
249	        let state = match (in_a.contains(path), in_b.contains(path)) {
250	            (true, false) => State::OnlyInA,
251	            (false, true) => State::OnlyInB,
252	            _ => {
253	                if std::fs::read(a.join(path))? == std::fs::read(b.join(path))? {
254	                    State::Same
255	                } else {
256	                    State::Differs
257	                }
258	            }
259	        };
260	        out.push((path.clone(), state));
261	    }
262	    if !custom && (a.join(CUSTOM_MD).is_file() || b.join(CUSTOM_MD).is_file()) {
263	        out.push((CUSTOM_MD.to_string(), State::ProjectLayer));
264	    }
265	    Ok(out)
266	}
267	
268	/// Render the comparison: one aligned line per file and a summary.
269	pub fn report(rows: &[(String, State)], a: &str, b: &str) -> String {
270	    let width = rows.iter().map(|(p, _)| p.len()).max().unwrap_or(0);
271	    let mut out = String::new();
272	    for (path, state) in rows {
273	        out.push_str(&format!("{path:<width$}  {}\n", state.label(a, b)));
274	    }
275	    let compared = rows
276	        .iter()
277	        .filter(|(_, s)| *s != State::ProjectLayer)
278	        .count();
279	    let differing = rows.iter().filter(|(_, s)| s.differs()).count();
280	    out.push_str(&format!("{differing} of {compared} differ\n"));
281	    out
282	}
283	
284	impl DiffArgs {
285	    /// Run the comparison. Non-zero when the sets differ, or on an
286	    /// error.
287	    pub fn run(&self) -> ExitCode {
288	        match self.diff() {
289	            Ok(true) => ExitCode::SUCCESS,
290	            Ok(false) => ExitCode::FAILURE,
291	            Err(e) => {
292	                error!("agent-files diff: {e}");
293	                ExitCode::FAILURE
294	            }
295	        }
296	    }
297	
298	    /// Print the report and say whether the sets are the same.
299	    fn diff(&self) -> Result<bool, Box<dyn std::error::Error>> {
300	        refuse_from_to("agent-files diff", &self.retired)?;
301	        let root = common::find_workspace_root();
302	        let cfg = match &root {
303	            Some(r) => super::config_at(r)?,
304	            None => super::WorkspaceAgentFiles::default(),
305	        };
306	        let template = match &root {
307	            Some(r) => family_template(r)?,
308	            None => None,
309	        };
310	        let a = resolve_set_dir(
311	            root.as_deref(),
312	            self.a.as_deref(),
313	            "agent-files.diff.dir",
314	            cfg.diff.dir.as_deref(),
315	            template.as_deref(),
316	        )?;
317	        let b = resolve_here(root.as_deref(), self.b.as_deref())?;
318	        let custom = resolve_custom(
319	            self.custom,
320	            self.no_custom,
321	            cfg.diff.custom,
322	            crate::config_schema::AGENT_FILES_DIFF_CUSTOM_DEFAULT,
323	        );
324	        info!(
325	            "agent-files diff: {} ({}) against {} ({})",
326	            a.shown, a.source, b.shown, b.source
327	        );
328	        let rows = compare(&a.path, &b.path, custom)?;
329	        info!("{}", report(&rows, &a.shown, &b.shown).trim_end());
330	        Ok(!rows.iter().any(|(_, s)| s.differs()))
331	    }
332	}
