29	/// A planned symlink operation.
30	#[derive(Debug)]
31	pub struct SymLink {
32	    /// Absolute path to the target directory (what the symlink points to).
33	    pub abs_target: PathBuf,
34	    /// Full path of the symlink to create/replace.
35	    pub symlink_path: PathBuf,
36	    /// What action is needed.
37	    pub action: SymlinkAction,
38	}
39	
40	/// Encode a path the way Claude Code does: every character that is
41	/// not an ASCII letter or digit becomes `-`.
42	///
43	/// - Claude Code's rule is `replace(/[^a-zA-Z0-9]/g, "-")`, which
44	///   runs over UTF-16 code units, so a character outside the Basic
45	///   Multilingual Plane becomes two dashes.
46	/// - Not reproduced: Claude Code cuts a name longer than 200
47	///   characters to 200 and appends a hash of the path.
48	/// - Source: the installed Claude Code binary, version 2.1.295,
49	///   read 2026-10-09.
50	pub fn encode_path(path: &str) -> String {
51	    let mut name = String::with_capacity(path.len());
52	    for c in path.chars() {
53	        if c.is_ascii_alphanumeric() {
54	            name.push(c);
55	        } else {
56	            (0..c.len_utf16()).for_each(|_| name.push('-'));
57	        }
58	    }
59	    name
60	}
61	
62	/// Read what exists at a path without following symlinks.
63	///
64	/// Returns:
65	/// - `None`: nothing exists
66	/// - `Some(None)`: exists but is not a symlink
67	/// - `Some(Some(target))`: symlink pointing to target
68	fn probe(path: &Path) -> Option<Option<PathBuf>> {
69	    match path.symlink_metadata() {
70	        Err(_) => None,
71	        Ok(meta) => {
72	            if meta.is_symlink() {
73	                // OK: TOCTOU race after symlink_metadata, so an empty PathBuf forces recreate
74	                Some(Some(std::fs::read_link(path).unwrap_or_default()))
75	            } else {
76	                Some(None)
77	            }
78	        }
79	    }
80	}
81	
82	impl SymLink {
83	    /// Plan a symlink operation by probing the filesystem.
84	    ///
85	    /// # Arguments
86	    /// * `cwd`: current working directory (used to derive the symlink name)
87	    /// * `target`: the directory the symlink should point to (resolved to absolute)
88	    /// * `symlink_dir`: parent directory for the symlink (e.g. `~/.claude/projects`)
89	    pub fn new(cwd: &Path, target: &Path, symlink_dir: &Path) -> Result<Self, String> {
90	        // Claude Code names a project by its real working directory,
91	        // which has no `.` or `..` in it, so the name is derived from
92	        // the same shape whatever the caller passed.
93	        let cwd = &crate::common::normalize_path(cwd);
94	        let abs_target = crate::common::normalize_path(&if target.is_absolute() {
95	            target.to_path_buf()
96	        } else {
97	            cwd.join(target)
98	        });
99	
100	        let cwd_str = cwd
101	            .to_str()
102	            .ok_or_else(|| "current directory path is not valid UTF-8".to_string())?;
103	        let symlink_name = encode_path(cwd_str);
104	        let symlink_path = symlink_dir.join(symlink_name);
105	
106	        let action = match probe(&symlink_path) {
107	            None => SymlinkAction::Create,
108	            Some(None) => {
109	                return Err(format!(
110	                    "'{}' exists and is not a symlink",
111	                    symlink_path.display()
112	                ));
113	            }
114	            Some(Some(current_target)) => {
115	                if current_target == abs_target {
116	                    SymlinkAction::AlreadyCorrect
117	                } else {
118	                    SymlinkAction::Replace { current_target }
119	                }
120	            }
121	        };
122	
123	        Ok(SymLink {
124	            abs_target,
125	            symlink_path,
126	            action,
127	        })
128	    }
129	
130	    /// Plan a symlink operation from pre-probed metadata (for testing).
131	    #[cfg(test)]
132	    pub fn with_meta(
133	        cwd: &Path,
134	        target: &Path,
135	        symlink_dir: &Path,
136	        symlink_meta: Option<Option<PathBuf>>,
137	    ) -> Result<Self, String> {
138	        // Claude Code names a project by its real working directory,
139	        // which has no `.` or `..` in it, so the name is derived from
140	        // the same shape whatever the caller passed.
141	        let cwd = &crate::common::normalize_path(cwd);
142	        let abs_target = crate::common::normalize_path(&if target.is_absolute() {
143	            target.to_path_buf()
144	        } else {
145	            cwd.join(target)
146	        });
147	
148	        let cwd_str = cwd
149	            .to_str()
150	            .ok_or_else(|| "current directory path is not valid UTF-8".to_string())?;
151	        let symlink_name = encode_path(cwd_str);
152	        let symlink_path = symlink_dir.join(symlink_name);
153	
154	        let action = match symlink_meta {
155	            None => SymlinkAction::Create,
156	            Some(None) => {
157	                return Err(format!(
158	                    "'{}' exists and is not a symlink",
159	                    symlink_path.display()
160	                ));
161	            }
162	            Some(Some(current_target)) => {
163	                if current_target == abs_target {
164	                    SymlinkAction::AlreadyCorrect
165	                } else {
166	                    SymlinkAction::Replace { current_target }
167	                }
168	            }
169	        };
170	
171	        Ok(SymLink {
172	            abs_target,
173	            symlink_path,
174	            action,
175	        })
176	    }
177	
178	    /// Execute the symlink operation: create the target dir if needed, create/replace the symlink.
179	    pub fn create(&self, create_target: bool) -> Result<(), String> {
180	        debug!(
181	            "symlink {} -> {}",
182	            self.symlink_path.display(),
183	            self.abs_target.display()
184	        );
185	
186	        if create_target && !self.abs_target.exists() {
187	            std::fs::create_dir_all(&self.abs_target).map_err(|e| {
188	                format!("cannot create target '{}': {e}", self.abs_target.display())
189	            })?;
190	        }
191	
192	        if let Some(parent) = self.symlink_path.parent() {
193	            std::fs::create_dir_all(parent).map_err(|e| {
194	                format!(
195	                    "cannot create symlink directory '{}': {e}",
196	                    parent.display()
197	                )
198	            })?;
199	        }
200	
201	        match &self.action {
202	            SymlinkAction::Create => {}
203	            SymlinkAction::Replace { .. } => {
204	                std::fs::remove_file(&self.symlink_path).map_err(|e| {
205	                    format!(
206	                        "cannot remove existing symlink '{}': {e}",
207	                        self.symlink_path.display()
208	                    )
209	                })?;
210	            }
211	            SymlinkAction::AlreadyCorrect => return Ok(()),
212	        }
213	
214	        #[cfg(unix)]
215	        std::os::unix::fs::symlink(&self.abs_target, &self.symlink_path).map_err(|e| {
216	            format!(
217	                "cannot create symlink '{}' -> '{}': {e}",
218	                self.symlink_path.display(),
219	                self.abs_target.display()
220	            )
221	        })?;
222	
223	        #[cfg(not(unix))]
224	        return Err("symlink creation is only supported on Unix".to_string());
225	
226	        Ok(())
227	    }
228	}
