1	//! What an init target already holds, read before init touches it.
2	//!
3	//! A fresh init creates everything and so wants an absent target.
4	//! `--adopt` grows what an existing target lacks, and what it lacks
5	//! depends on which of these states the target is in.
6	
7	use std::path::Path;
8	
9	use crate::toml_simple;
10	
11	/// The state of an init target directory.
12	#[derive(Debug, PartialEq, Eq)]
13	pub(crate) enum TargetState {
14	    /// Nothing there: the fresh-create path.
15	    Absent,
16	    /// A directory that is no repo: both repos are to be grown, its
17	    /// content the work repo's first commit.
18	    PlainDir,
19	    /// A repo with no workspace config: the agent side is to be grown
20	    /// beside it, its history left alone.
21	    Por,
22	    /// A repo whose config declares the work side only: the agent
23	    /// side is to be grown and the config given its entry.
24	    SingleRepo,
25	    /// A repo whose config already declares an agent side: nothing to
26	    /// grow, so init refuses it.
27	    Dual,
28	}
29	
30	impl TargetState {
31	    /// How a message names the state.
32	    pub(crate) fn describe(&self) -> &'static str {
33	        match self {
34	            TargetState::Absent => "absent",
35	            TargetState::PlainDir => "a plain directory with no repo",
36	            TargetState::Por => "a repo with no workspace config",
37	            TargetState::SingleRepo => "a single-repo workspace",
38	            TargetState::Dual => "a dual-repo workspace",
39	        }
40	    }
41	}
42	
43	/// Read what `dir` holds.
44	///
45	/// A repo is a `.git` or a `.jj` in `dir` itself. The workspace
46	/// config is whichever carrier `dir` holds, and its `repos.agent`
47	/// decides single-repo against dual, so a dual workspace's agent
48	/// repo, whose config declares `agent = "."`, reads as dual too.
49	///
50	/// Errors, rather than a state, for what no state describes and init
51	/// must not guess at:
52	///
53	/// - `dir` is a file.
54	/// - a config with no repo beside it, or one whose `[repos]` registry
55	///   declares no work side, which is a legacy config or a broken one.
56	pub(crate) fn detect_target_state(dir: &Path) -> Result<TargetState, Box<dyn std::error::Error>> {
57	    if !dir.exists() {
58	        return Ok(TargetState::Absent);
59	    }
60	    if !dir.is_dir() {
61	        return Err(format!("'{}' exists and is not a directory", dir.display()).into());
62	    }
63	    let is_repo = dir.join(".git").exists() || dir.join(".jj").exists();
64	    let Some(cfg) = crate::config_md::load(dir)? else {
65	        return Ok(if is_repo {
66	            TargetState::Por
67	        } else {
68	            TargetState::PlainDir
69	        });
70	    };
71	    if !is_repo {
72	        return Err(format!(
73	            "'{}' holds a workspace config but no repo",
74	            cfg.path.display()
75	        )
76	        .into());
77	    }
78	    crate::common::reject_legacy_config(dir)?;
79	    if toml_simple::toml_get(&cfg.map, "repos.work").is_none() {
80	        return Err(format!(
81	            "{}: declares no repos.work, so it is no workspace config init can read",
82	            cfg.path.display()
83	        )
84	        .into());
85	    }
86	    Ok(
87	        match toml_simple::toml_get(&cfg.map, "repos.agent").filter(|v| !v.is_empty()) {
88	            Some(_) => TargetState::Dual,
89	            None => TargetState::SingleRepo,
90	        },
91	    )
92	}
93	
94	/// Whether `dir` is a git repo with no jj, which adopt colocates
95	/// before it grows it.
96	pub(crate) fn is_git_only(dir: &Path) -> bool {
97	    dir.join(".git").exists() && !dir.join(".jj").exists()
98	}
99	
100	/// Check that a repo adopt is to grow is one it can: colocated with
101	/// git, or git alone, which adopt colocates, since vc-x1 reads both
102	/// halves. A jj repo whose git store is internal is refused, having
103	/// no `.git` for git to use.
104	pub(crate) fn check_colocation(dir: &Path) -> Result<(), Box<dyn std::error::Error>> {
105	    let (jj, git) = (dir.join(".jj").exists(), dir.join(".git").exists());
106	    if jj && !git {
107	        return Err(format!(
108	            "--adopt: '{}' is a jj repo not colocated with git: vc-x1 needs a colocated repo",
109	            dir.display()
110	        )
111	        .into());
112	    }
113	    Ok(())
114	}
115	
116	/// Colocate a git-only repo with jj, in place, its history kept.
117	pub(crate) fn colocate(dir: &Path) -> Result<(), Box<dyn std::error::Error>> {
118	    crate::jj::git_init_colocated_existing(dir)
119	}
120	
121	/// Check that a colocated repo's working copy is clean, since adopt's
122	/// commit would otherwise take the uncommitted work in.
123	///
124	/// A repo with no commit yet, as `cargo init` and `git init` leave
125	/// one, has no history for adopt's commit to go on top of, so its
126	/// content is the commit's, as a plain directory's is.
127	pub(crate) fn check_clean(dir: &Path) -> Result<(), Box<dyn std::error::Error>> {
128	    let unborn = !crate::jj::cids_of(dir, "@- & root()")?.is_empty();
129	    let clean = crate::jj::is_empty(dir, "@")? && crate::jj::desc_of(dir, "@")?.trim().is_empty();
130	    if !unborn && !clean {
131	        return Err(format!(
132	            "--adopt: '{}' has uncommitted work in @: commit it first, since adopt adds a \
133	             commit of its own on top",
134	            dir.display()
135	        )
136	        .into());
137	    }
138	    Ok(())
139	}
140	
141	/// Add the agent side to a single-repo workspace's config, in place.
142	///
143	/// Only lines are added: `agent = "<agent_dir>"` after the last key of
144	/// `[repos]`, and `agent-repo = "<agent_repo>"` under `[remote]`, a
145	/// header added after the `agent` line when the file has none. The
146	/// prose, the comments, and every other key stay as they are, since
147	/// the file is the user's. The result is read back, and a file that
148	/// does not then declare both keys is restored and refused.
149	pub(crate) fn add_agent_to_config(
150	    dir: &Path,
151	    agent_dir: &str,
152	    agent_repo: &str,
153	) -> Result<(), Box<dyn std::error::Error>> {
154	    let path = crate::config_md::vc_config_path(dir)?
155	        .ok_or_else(|| format!("'{}' holds no workspace config to edit", dir.display()))?;
156	    let original = std::fs::read_to_string(&path)
157	        .map_err(|e| format!("cannot read '{}': {e}", path.display()))?;
158	    let fenced = path.extension().is_some_and(|e| e == "md");
159	    let edited = add_agent_keys(&original, fenced, agent_dir, agent_repo)
160	        .map_err(|e| format!("{}: {e}", path.display()))?;
161	    crate::common::write_file(&path, &edited)?;
162	
163	    let map = crate::config_md::load_file(&path)?;
164	    let reads = |key: &str| toml_simple::toml_get(&map, key).map(String::as_str);
165	    if reads("repos.agent") != Some(agent_dir) || reads("remote.agent-repo") != Some(agent_repo) {
166	        crate::common::write_file(&path, &original)?;
167	        return Err(format!(
168	            "{}: the edited config did not read back with repos.agent and remote.agent-repo, so \
169	             it was restored: add them by hand, then adopt",
170	            path.display()
171	        )
172	        .into());
173	    }
174	    Ok(())
175	}
176	
177	/// The lines-only edit behind [`add_agent_to_config`].
178	///
179	/// `fenced` is a markdown carrier, whose TOML is its ```` ```toml ````
180	/// fences read as one document, so a table runs on across fences.
181	/// Otherwise the whole text is TOML.
182	pub(crate) fn add_agent_keys(
183	    text: &str,
184	    fenced: bool,
185	    agent_dir: &str,
186	    agent_repo: &str,
187	) -> Result<String, String> {
188	    let lines: Vec<&str> = text.lines().collect();
189	    let mut in_toml = vec![!fenced; lines.len()];
190	    if fenced {
191	        let mut open = false;
192	        for (i, line) in lines.iter().enumerate() {
193	            let t = line.trim();
194	            if !open && t == "```toml" {
195	                open = true;
196	            } else if open && t.starts_with("```") {
197	                open = false;
198	            } else {
199	                in_toml[i] = open;
200	            }
201	        }
202	    }
203	
204	    let mut table: Option<&str> = None;
205	    let mut repos_last_key = None;
206	    let mut remote_header = None;
207	    for (i, line) in lines.iter().enumerate() {
208	        if !in_toml[i] {
209	            continue;
210	        }
211	        let t = line.trim();
212	        if t.starts_with('[') && t.ends_with(']') && !t.starts_with("[[") {
213	            let name = t[1..t.len() - 1].trim();
214	            if name == "remote" {
215	                remote_header = Some(i);
216	            }
217	            table = Some(name);
218	        } else if !t.is_empty() && !t.starts_with('#') && table == Some("repos") {
219	            repos_last_key = Some(i);
220	        }
221	    }
222	    let last = repos_last_key.ok_or("no [repos] table with a key under it")?;
223	
224	    let indent: String = lines[last]
225	        .chars()
226	        .take_while(|c| c.is_whitespace())
227	        .collect();
228	    let agent_line = format!("{indent}agent = \"{agent_dir}\"");
229	    let repo_line = format!("agent-repo = \"{agent_repo}\"");
230	    let mut out: Vec<String> = Vec::with_capacity(lines.len() + 4);
231	    for (i, line) in lines.iter().enumerate() {
232	        out.push((*line).to_string());
233	        if i == last {
234	            out.push(agent_line.clone());
235	            if remote_header.is_none() {
236	                out.push(String::new());
237	                out.push("[remote]".to_string());
238	                out.push(repo_line.clone());
239	            }
240	        }
241	        if Some(i) == remote_header {
242	            out.push(repo_line.clone());
243	        }
244	    }
245	    let mut edited = out.join("\n");
246	    if text.ends_with('\n') {
247	        edited.push('\n');
248	    }
249	    Ok(edited)
250	}
